const raw = $input.first().json;
const body = raw.body || raw;

const sessionId = body.session_id  || null;
const dealerId  = body.dealer_id   || null;
const event     = body.event       || 'message';
const message   = body.message     || '';
const language  = body.language    || 'es';

// Vehicle context (present on session_start)
const vehicle  = body.vehicle  || null;
const showroom = body.showroom || null;

if (!sessionId || !dealerId) {
  return [{ json: { _error: 'missing_session_or_dealer', sessionId, dealerId, event, message, language, vehicle, showroom } }];
}

return [{ json: { sessionId, dealerId, event, message, language, vehicle, showroom, _error: null } }];

const d = $input.first().json;
const v = d.vehicle || {};
const s = d.showroom || {};
const lang = d.language || 'es';
function whatsappLink(raw) { const digits = String(raw || '').replace(/[^0-9]/g, ''); if (!digits) return null; const normalized = digits.length === 9 ? '34' + digits : digits; return 'https://wa.me/' + normalized; }
const waLink = whatsappLink(s.whatsapp);
const priceText = v.price && !v.price_on_request ? 'Precio: ' + new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 }).format(v.price) : (v.price_on_request ? 'Precio: A consultar' : null);
const CONDITION_LABELS = { new: 'Nuevo', seminuevo: 'Seminuevo', ocasion: 'Ocasión', clasico: 'Clásico', restaurado: 'Restaurado', preparado: 'Preparado', coleccion: 'Colección' };
const conditionLabel = v.condition ? (CONDITION_LABELS[v.condition] || v.condition) : null;
const vehicleInfo = [
  v.title ? 'Vehículo: ' + v.title : null,
  priceText,
  v.year ? 'Año: ' + v.year : null,
  v.fuel_type ? 'Combustible: ' + v.fuel_type : null,
  v.mileage_km ? 'Kilómetros: ' + new Intl.NumberFormat('es-ES').format(v.mileage_km) + ' km' : null,
  v.power_hp ? 'Potencia: ' + v.power_hp + ' CV' : null,
  conditionLabel ? 'Estado: ' + conditionLabel : null,
  v.registration_country ? 'País de origen: ' + v.registration_country : null,
  v.location_province ? 'Ubicación: ' + v.location_province : null,
  v.num_owners != null ? 'Número de propietarios: ' + v.num_owners : null,
  v.has_service_history ? 'Historial de mantenimiento: disponible (consultar con el showroom para el detalle)' : null,
  v.has_carfax ? 'Informe Carfax: disponible (consultar con el showroom para el detalle)' : null,
  v.itv_valid_until ? 'ITV válida hasta: ' + v.itv_valid_until : null,
  Array.isArray(v.equipment) && v.equipment.length ? 'Equipamiento destacado: ' + v.equipment.join(', ') : null,
  v.description ? 'Descripción del vendedor: ' + v.description : null,
].filter(Boolean).join('\n');
const showroomInfo = [s.name ? 'Showroom: ' + s.name : null, s.city ? 'Ciudad: ' + s.city : null, s.whatsapp ? 'WhatsApp: ' + s.whatsapp : null, waLink ? 'Enlace WhatsApp: ' + waLink : null, s.description ? 'Sobre el showroom: ' + s.description : null].filter(Boolean).join('\n');

const SERVICE_LABELS = { financing: 'Financiación', trade_in: 'Aceptan vehículos a cuenta', warranty: 'Garantía', transport_nat: 'Transporte nacional', transport_intl: 'Transporte internacional', own_workshop: 'Taller propio', detailing: 'Detailing', home_delivery: 'Entrega a domicilio' };
const services = Array.isArray(s.services) ? s.services.map((k) => SERVICE_LABELS[k] || k).filter(Boolean) : [];
const commercialLines = [
  s.financing_available ? 'Financiación: sí ofrecen' + (s.financing_conditions ? ' — ' + s.financing_conditions : '') : (s.financing_available === false ? 'Financiación: no ofrecen' : null),
  s.attention_hours ? 'Horario de atención: ' + s.attention_hours : null,
  s.negotiation_style ? 'Cómo negocian: ' + s.negotiation_style : null,
  services.length ? 'Servicios adicionales: ' + services.join(', ') : null,
].filter(Boolean);
const commercialInfo = commercialLines.length ? commercialLines.join('\n') : null;

const contactRule = waLink ? 'Cuando el comprador muestre intención real, ofrece dos vías con naturalidad: reservar una visita si está disponible o hablar directamente por WhatsApp en ' + waLink + '. No fuerces el enlace al inicio; úsalo cuando ayude a avanzar la conversación.' : 'Cuando el comprador muestre intención real, sugiere reservar una visita o dejar datos para que el showroom le contacte.';
const systemPrompt = 'Eres el asistente de ventas de ' + (s.name || 'este showroom') + ' en Black Label Market, especializado en vehículos premium.\n\nINFORMACIÓN DEL VEHÍCULO:\n' + (vehicleInfo || 'No disponible') + '\n\nINFORMACIÓN DEL SHOWROOM:\n' + (showroomInfo || 'No disponible') + (commercialInfo ? '\n\nCÓMO TRABAJA ESTE SHOWROOM (usa esto para responder con datos reales, no genéricos):\n' + commercialInfo : '') + '\n\nTu objetivo:\n1. Responder preguntas sobre el vehículo con información precisa, incluido historial, procedencia, equipamiento y estado cuando se te haya dado el dato.\n2. Entender necesidades del comprador: uso, financiación, plazo de compra y posible vehículo a entregar. Si preguntan por financiación, condiciones de negociación, horario o servicios, usa SIEMPRE los datos reales de arriba en vez de dar una respuesta genérica — si un dato no aparece arriba, dilo con claridad en vez de inventarlo.\n3. ' + contactRule + '\n4. Ser conciso: 2-3 frases, tono profesional, sobrio y cercano.\n5. Idioma: ' + (lang === 'es' ? 'Español' : lang) + '.\n\nNo inventes características del vehículo ni condiciones comerciales que no se te hayan dado. \"Historial de mantenimiento\" y \"Carfax\" indican que el vendedor declara tenerlos disponibles, no que Black Label Market los haya verificado — si preguntan por el detalle exacto, deriva al showroom. Si falta un dato, dilo con claridad y ofrece consultarlo con el showroom.';
const openingMessage = lang === 'es' ? 'Hola, soy el asistente de ' + (s.name || 'este showroom') + '. Puedo ayudarte con ' + (v.title || 'esta unidad') + ' y coordinar el siguiente paso si encaja con lo que buscas. ¿Qué te gustaría saber?' : 'Hi, I am the assistant for ' + (s.name || 'this showroom') + '. I can help with ' + (v.title || 'this vehicle') + ' and coordinate the next step if it fits what you are looking for. What would you like to know?';
return [{ json: { ...d, systemPrompt, openingMessages: [{ role: 'system', content: systemPrompt }, { role: 'assistant', content: openingMessage }], openingMessage } }];

const input = $('Switch por tipo de evento').first().json;
const rows = $input.all();
const session = rows.length > 0 ? rows[0].json : null;
const history = Array.isArray(session?.messages) ? session.messages : [];
const storedSystemPrompt = history.find(m => m?.role === 'system' && m?.content)?.content;
const systemPrompt = storedSystemPrompt || 'Eres el asistente de ventas de un showroom premium en Black Label Market.\nResponde de forma concisa (2-3 frases), profesional y útil.\nSi el comprador muestra interés real en comprar, sugiere contactar por WhatsApp si está disponible o concertar visita.\nNo inventes información que no tengas.';
const recentHistory = history.filter(m => m?.role !== 'system').slice(-10);
const messages = [{ role: 'system', content: systemPrompt }, ...recentHistory, { role: 'user', content: input.message }];
return [{ json: { ...input, messages, history } }];

const openaiResp = $input.first().json;
const prevData   = $('Construir request OpenAI').first().json;

const aiMessage = openaiResp?.choices?.[0]?.message?.content || 'Lo siento, no he podido procesar tu mensaje. Por favor, inténtalo de nuevo.';

const updatedHistory = [
  ...prevData.history,
  { role: 'user',      content: prevData.message },
  { role: 'assistant', content: aiMessage }
];

// Keep only last 20 messages to limit storage
const trimmedHistory = updatedHistory.slice(-20);

return [{ json: { ...prevData, aiMessage, updatedHistory: trimmedHistory } }];
